<?php defined( 'ABSPATH' ) || exit; get_header(); ?>
<div class="container section-pad"><div class="section-heading"><span class="eyebrow"><?php echo esc_html( canarw_label( 'المستجدات', 'Journal' ) ); ?></span><h1><?php echo esc_html( is_archive() ? get_the_archive_title() : ( is_search() ? sprintf( canarw_label( 'نتائج البحث: %s', 'Search: %s' ), get_search_query() ) : canarw_label( 'آخر الأخبار', 'Latest updates' ) ) ); ?></h1></div>
